"""scripts/README.md is generated by scripts_index.py and lists every script exactly once."""
import pathlib
import re
import unittest

import scripts_index


class ScriptsIndexTests(unittest.TestCase):
    def test_readme_is_current(self):
        current = scripts_index.README.read_text(encoding="utf-8").replace("\r\n", "\n")
        self.assertEqual(scripts_index.render(), current,
                         "scripts/README.md is stale; run python -B scripts/scripts_index.py")

    def test_every_script_is_listed_exactly_once(self):
        text = scripts_index.render()
        scripts = scripts_index.SCRIPTS
        expected = [p.name for p in scripts.iterdir() if p.is_file() and p.name != "README.md"]
        expected += [p.name for p in (scripts / "tests").glob("test_*.py")]
        listed = re.findall(r"\[`([^`]+)`\]\(", text)  # prose may name a file again, unlinked
        counts = {name: listed.count(name) for name in expected}
        self.assertEqual({}, {name: n for name, n in counts.items() if n != 1})

    def test_moved_unit_tests_do_not_shadow_top_level_modules(self):
        scripts = scripts_index.SCRIPTS
        top = {p.name for p in scripts.glob("*.py")}
        self.assertEqual(set(), top & {p.name for p in (scripts / "tests").glob("*.py")})

    def test_tests_folder_holds_only_unit_tests(self):
        tests = pathlib.Path(scripts_index.SCRIPTS / "tests")
        self.assertEqual([], [p.name for p in tests.iterdir() if p.is_file() and not re.fullmatch(r"test_\w+\.py", p.name)])


if __name__ == "__main__":
    unittest.main()
